const binary = (op,a,z) => ({'+':()=>a+z,'-':()=>a-z,'*':()=>a*z,'/':()=>Math.trunc(a/z),'%':()=>a%z,'<':()=>a<z,'>':()=>a>z,'<=':()=>a<=z,'>=':()=>a>=z,'==':()=>a===z,'!=':()=>a!==z,'&&':()=>a&&z,'||':()=>a||z,'&':()=>a&z,'|':()=>a|z,'^':()=>a^z,'<<':()=>a<<z,'>>':()=>a>>z}[op]());
function evaluateExpression(expr, env) { return Array.isArray(expr) ? binary(expr[0],evaluateExpression(expr[1],env),evaluateExpression(expr[2],env)) : typeof expr==='string' ? env[expr] : expr; }
export function evaluateTopic(topic, variant, trace = []) {
 const env={...topic.inputs(variant)};
 trace.push(Object.entries(env).map(([key,value])=>`${key} = ${value}`).join(', '));
 function execute(statements, record = true) {
  for(const [kind,...args] of statements){
   if(kind==='set') { env[args[0]]=evaluateExpression(args[1],env); if(record)trace.push(`${args[0]} = ${expression(args[1], 'cpp')} → ${env[args[0]]}`); }
   if(kind==='return') {const value=evaluateExpression(args[0],env);if(record)trace.push(`return ${expression(args[0], 'cpp')} → ${value}`);return {value};}
   if(kind==='if'){ const yes=!!evaluateExpression(args[0],env);if(record)trace.push(`${expression(args[0], 'cpp')} → ${yes}`); const result=execute(yes?args[1]:args[2],record);if(result)return result; }
   if(kind==='for') { const count=evaluateExpression(args[1],env);if(record)trace.push(`${args[0]}: 0 .. ${count-1}`); for(env[args[0]]=0;env[args[0]]<count;env[args[0]]++){const result=execute(args[2],false);if(result)return result;} if(record)trace.push(Object.entries(env).map(([key,value])=>`${key} = ${value}`).join(', ')); }
  }
 }
 return execute(topic.body)?.value;
}
const camel = name=>name.replace(/_([a-z])/g,(_,letter)=>letter.toUpperCase());
export function functionName(language, id) { const name=['csharp','java','go'].includes(language)?camel(id):id;return language==='csharp'?name[0].toUpperCase()+name.slice(1):name; }
function expression(expr, language) {
 if(!Array.isArray(expr)) return String(expr);
 let [op,left,right]=expr;
 if(language==='lua'&&op==='^') op='~';
 if(language==='lua'&&op==='!=') op='~=';
 if(['python','lua'].includes(language)) op=({'&&':'and','||':'or','/':'//'})[op]||op;
 return `(${expression(left,language)} ${op} ${expression(right,language)})`;
}
export function renderTopic(language, topic, variant) {
 const name=functionName(language,topic.id), python=language==='python',lua=language==='lua';
 const comment=python?'#':'//';
 const lines=[python?`def ${name}():`:lua?`function ${name}()` : language==='rust'?`fn ${name}() -> i32 {`:language==='go'?`func ${name}() int {`:['java','csharp'].includes(language)?`static int ${name}() {`:`int ${name}() {`];
 const pad=n=>'    '.repeat(n), end=python||lua?'':';';
 lines.push(`${pad(1)}${lua?'--':comment} ${topic.comments[0].en}`);
 for(const [key,value] of Object.entries(topic.inputs(variant))) lines.push(`${pad(1)}${python?`${key} = ${value}`:lua?`local ${key} = ${value}`:language==='rust'?`let mut ${key}: i32 = ${value};`:language==='go'?`${key} := ${value}`:`int ${key} = ${value};`}`);
 lines.push(`${pad(1)}${lua?'--':comment} ${topic.comments[1].en}`);
 function emit(body,depth){for(const [kind,...args] of body){
  if(kind==='set') lines.push(`${pad(depth)}${args[0]} = ${expression(args[1],language)}${end}`);
  if(kind==='return') lines.push(`${pad(depth)}return ${expression(args[0],language)}${end}`);
  if(kind==='if'){
   const condition=expression(args[0],language);
   lines.push(`${pad(depth)}${python?`if ${condition}:`:lua?`if ${condition} then`:language==='go'||language==='rust'?`if ${condition} {`:`if (${condition}) {`}`);
   emit(args[1],depth+1);
   if(args[2].length){lines.push(`${pad(depth)}${python?'else:':lua?'else':'} else {'}`);emit(args[2],depth+1);}
   if(!python) lines.push(`${pad(depth)}${lua?'end':'}'}`);
  }
  if(kind==='for'){
   const [variable,limit,block]=args, bound=expression(limit,language);
   lines.push(`${pad(depth)}${python?`for ${variable} in range(${bound}):`:lua?`for ${variable} = 0, ${bound} - 1 do`:language==='rust'?`for ${variable} in 0..${bound} {`:language==='go'?`for ${variable} := 0; ${variable} < ${bound}; ${variable}++ {`:`for (int ${variable} = 0; ${variable} < ${bound}; ${variable}++) {`}`);
   emit(block,depth+1);if(!python)lines.push(`${pad(depth)}${lua?'end':'}'}`);
  }
 }}
 emit(topic.body,1);if(!python)lines.push(lua?'end':'}');
 return lines.join('\n');
}

// SQL examples use real relational operations and a small, reproducible table.
// Each query returns one scalar so its result can be checked by a reader.
const sum = values=>values.reduce((a,z)=>a+z,0);
const max = rows=>Math.max(...rows.map(r=>r.amount));
const min = rows=>Math.min(...rows.map(r=>r.amount));
